record Article(int id, String title, boolean published, double rating) {}

String mapJavaTypeToOpenApi(Class<?> type) {
    if (type == int.class || type == long.class || type == Integer.class) return "integer";
    if (type == double.class || type == float.class || type == Double.class) return "number";
    if (type == boolean.class || type == Boolean.class) return "boolean";
    return "string";
}

Map<String, String> generateSchema(Class<?> recordClass) {
    Map<String, String> schema = new LinkedHashMap<>();
    for (var field : recordClass.getDeclaredFields()) {
        schema.put(field.getName(), mapJavaTypeToOpenApi(field.getType()));
    }
    return schema;
}
